async function createSession(
  request: Request,
  env: WorkerEnv,
): Promise<Response> {
  const body = await bodyObject(request);
  const nickname = requireString(body.nickname).trim();
  if (!/^[\p{L}\p{N} _-]{2,16}$/u.test(nickname))
    throw new DomainError("INVALID_NICKNAME");
  const now = new Date();
  const token = randomSecret();
  const session: SessionRecord = {
    id: crypto.randomUUID(),
    accountId: null,
    nickname,
    tokenHash: await sha256(token),
    createdAt: now.toISOString(),
    lastSeenAt: now.toISOString(),
    currentRoomId: null,
    expiresAt: new Date(
      now.getTime() + SESSION_TTL_SECONDS * 1000,
    ).toISOString(),
  };
  const stored = await internalJson<SessionRecord>(
    accounts(env).fetch(
      internalRequest("/sessions/create", {
        sessionId: session.id,
        accountId: session.accountId,
        nickname: session.nickname,
        tokenHash: session.tokenHash,
        createdAt: session.createdAt,
        lastSeenAt: session.lastSeenAt,
        currentRoomId: session.currentRoomId,
        expiresAt: session.expiresAt,
      }),
    ),
    201,
  );
  return json(publicSession(stored), 201, {
    "set-cookie": sessionCookie(token, request.url, SESSION_TTL_SECONDS),
  });
}

async function upgradeAccount(
  request: Request,
  env: WorkerEnv,
): Promise<Response> {
  const token = requireToken(request);
  const session = await authenticate(request, env);
  if (session.accountId) throw new DomainError("INVALID_STATE");
  const body = await bodyObject(request);
  const handle = requireString(body.handle).trim();
  if (!/^[\p{L}\p{N}_-]{2,16}$/u.test(handle))
    throw new DomainError("INVALID_NICKNAME");
  const recoveryKey = randomSecret();
  const nextToken = randomSecret();
  const result = await internalJson<{
    account: PlayerAccount;
    session: SessionRecord;
  }>(
    accounts(env).fetch(
      internalRequest("/accounts/upgrade", {
        tokenHash: await sha256(token),
        nextTokenHash: await sha256(nextToken),
        handle,
        accountId: crypto.randomUUID(),
        recoveryKeyHash: await sha256(recoveryKey),
        now: new Date().toISOString(),
      }),
    ),
  );
  await internalJson(
    progression(env).fetch(
      internalRequest("/identities/migrate", {
        sourceId: session.id,
        accountId: result.account.id,
        handle: result.account.handle,
      }),
    ),
    204,
  );
  return json(
    {
      account: {
        id: result.account.id,
        handle: result.account.handle,
        createdAt: result.account.createdAt,
      },
      recoveryKey,
    },
    200,
    {
      "set-cookie": sessionCookie(nextToken, request.url, SESSION_TTL_SECONDS),
    },
  );
}

