async function websocket(request: Request, env: WorkerEnv): Promise<Response> {
  try {
    if (request.headers.get("upgrade")?.toLowerCase() !== "websocket") {
      return json({ code: "UPGRADE_REQUIRED" }, 426);
    }
    const url = new URL(request.url);
    await enforceRateLimit(request, env, "websocket", 60, 60_000);
    const origin = request.headers.get("origin");
    if (origin && origin !== url.origin) throw new DomainError("UNAUTHORIZED");
    const session = await authenticate(request, env);
    if (!session.currentRoomId) throw new DomainError("NOT_ROOM_MEMBER");
    const headers = new Headers(request.headers);
    headers.set("x-mk01-session-id", session.id);
    return room(env, session.currentRoomId).fetch(
      new Request("https://internal.mk01/websocket", {
        method: "GET",
        headers,
      }),
    );
  } catch (error) {
    return errorResponse(error);
  }
}

async function enforceHttpRateLimits(
  request: Request,
  env: WorkerEnv,
): Promise<void> {
  const pathname = new URL(request.url).pathname;
  const checks = [enforceRateLimit(request, env, "http-ip", 600, 60_000)];
  const token = cookieValue(request);
  if (token)
    checks.push(
      enforceRateLimit(request, env, "http-session", 240, 60_000, token),
    );
  if (request.method === "POST" && pathname === "/api/sessions") {
    checks.push(enforceRateLimit(request, env, "session-create", 20, 60_000));
  }
  await Promise.all(checks);
}

async function enforceRateLimit(
  request: Request,
  env: WorkerEnv,
  category: string,
  limit: number,
  windowMs: number,
  identity?: string,
): Promise<void> {
  const client =
    identity ??
    request.headers.get("cf-connecting-ip") ??
    request.headers.get("x-real-ip") ??
    "local-client";
  const key = await sha256(`${category}:${client}`);
  const limiter = env.RATE_LIMITS.get(env.RATE_LIMITS.idFromName(key));
  await internalJson(
    limiter.fetch(
      internalRequest("/check", { limit, windowMs, now: Date.now() }),
    ),
    204,
  );
}

async function authenticate(
  request: Request,
  env: WorkerEnv,
): Promise<SessionRecord> {
  const token = requireToken(request);
  return internalJson<SessionRecord>(
    accounts(env).fetch(
      internalRequest("/sessions/authenticate", {
        tokenHash: await sha256(token),
        now: new Date().toISOString(),
      }),
    ),
  );
}

async function updateSessionRoom(
  env: WorkerEnv,
  token: string,
  roomId: string | null,
): Promise<void> {
  await internalJson(
    accounts(env).fetch(
      internalRequest("/sessions/room", {
        tokenHash: await sha256(token),
        roomId,
      }),
    ),
    204,
  );
}

interface RevokedSession {
  sessionId: string;
  roomId: string | null;
}

async function disconnectRevokedSession(
  env: WorkerEnv,
  revoked: RevokedSession,
): Promise<void> {
  await internalJson(
    matchmaking(env).fetch(
      internalRequest("/cancel", { sessionId: revoked.sessionId }),
    ),
    204,
  );
  if (!revoked.roomId) return;
  await internalJson(
    room(env, revoked.roomId).fetch(
      internalRequest("/disconnect-session", {
        sessionId: revoked.sessionId,
        now: new Date().toISOString(),
      }),
    ),
    204,
  );
}

